//! Stable product-facing MCP tools for Layers' context compiler surface.
//!
//! This module keeps the public MCP surface centered on `ContextPacket` and
//! read-only context retrieval. It deliberately does not register generic
//! runtime/process/filesystem/subagent capabilities.

use layers_compiler::{
    CompileMode, CompileRequest, ContextCompiler, cited_item, context_section, source,
};
use layers_core::{
    ContextBudget, ContextPacket, ContextSection, LayersError, Result, Tool, ToolContext,
    ToolOutput,
};
use layers_tools::memory::{MemoryGetTool, MemorySearchTool};
use layers_tools::registry::ToolRegistry;
use serde::Deserialize;
use uuid::Uuid;

use crate::server::STABLE_CONTEXT_SURFACE_TOOLS;

/// Build the stable product-facing MCP registry.
///
/// The registry contains only context compilation, read-only memory retrieval,
/// code-impact summarization, and context packet validation tools. Server-side
/// exposure is still controlled by `McpServerConfig::stable_context_surface()`.
#[must_use]
pub fn stable_context_registry() -> ToolRegistry {
    let mut registry = ToolRegistry::new();
    registry.register(std::sync::Arc::new(ContextCompileTool));
    registry.register(std::sync::Arc::new(PreflightContextTool));
    registry.register(std::sync::Arc::new(ImpactAnalyzeTool));
    registry.register(std::sync::Arc::new(MemoryGetTool::new()));
    registry.register(std::sync::Arc::new(MemorySearchTool::new()));
    registry.register(std::sync::Arc::new(ValidateContextTool));
    registry
}

/// Returns `true` when a tool is part of the stable context compiler surface.
#[must_use]
pub fn is_stable_context_tool(name: &str) -> bool {
    STABLE_CONTEXT_SURFACE_TOOLS.contains(&name)
}

/// Compile an agent-ready `ContextPacket` from explicit MCP inputs.
pub struct ContextCompileTool;

#[derive(Debug, Deserialize)]
struct ContextCompileParams {
    #[serde(default)]
    task: Option<String>,
    #[serde(default)]
    query: Option<String>,
    #[serde(default)]
    workspace_id: Option<String>,
    #[serde(default)]
    git_ref: Option<String>,
    #[serde(default)]
    max_units: Option<usize>,
    #[serde(default)]
    evidence: Vec<ContextEvidenceParam>,
}

#[derive(Debug, Deserialize)]
struct PreflightContextParams {
    #[serde(default)]
    task: Option<String>,
    #[serde(default)]
    query: Option<String>,
    #[serde(default)]
    workspace_id: Option<String>,
    #[serde(default)]
    git_ref: Option<String>,
    #[serde(default)]
    max_units: Option<usize>,
    #[serde(default)]
    targets: Vec<String>,
    #[serde(default)]
    evidence: Vec<ContextEvidenceParam>,
}

//! MCP server: expose Layers tools as an MCP server via stdio JSON-RPC.
//!
//! Tools are only exposed if explicitly allowlisted. Dangerous tools (those that
//! mutate state — exec, process, subagent, fs-write, edit) are blocked by
//! default unless `expose_dangerous` is set to `true` in the server config.

use std::collections::HashSet;
use std::sync::Arc;

use serde::{Deserialize, Serialize};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tracing::{debug, error, warn};

use layers_core::{Result, ToolContext};
use layers_tools::registry::ToolRegistry;

// ---------------------------------------------------------------------------
// Dangerous-tool patterns
// ---------------------------------------------------------------------------

/// Substrings that mark a tool name as dangerous (mutating / side-effectful).
const DANGEROUS_PATTERNS: &[&str] = &[
    "exec", "execute", "run", "spawn", "process", "subagent", "write", "edit", "delete", "remove",
    "create", "mutate", "update", "kill", "stop",
];

/// Stable product-facing MCP tools for Layers' context compiler surface.
///
/// This surface is intentionally narrow: it exposes context packet compilation,
/// memory retrieval, code-impact analysis, and context validation. Generic
/// runtime tools such as filesystem mutation, process execution, and subagent
/// control must remain behind explicit allowlists and dangerous-tool opt-in.
pub const STABLE_CONTEXT_SURFACE_TOOLS: &[&str] = &[
    "context_compile",
    "impact_analyze",
    "memory_get",
    "memory_search",
    "preflight_context",
    "validate_context",
];

/// Returns `true` if the tool name matches any dangerous pattern.
pub fn is_dangerous_tool(name: &str) -> bool {
    let lower = name.to_lowercase();
    DANGEROUS_PATTERNS
        .iter()
        .any(|pattern| lower.contains(pattern))
}

/// Stable context compiler MCP tool names in deterministic listing order.
#[must_use]
pub fn stable_context_surface_tools() -> Vec<&'static str> {
    STABLE_CONTEXT_SURFACE_TOOLS.to_vec()
}

// ---------------------------------------------------------------------------
// Server config
// ---------------------------------------------------------------------------

/// Configuration for the MCP server.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct McpServerConfig {
    /// Server name announced during initialization.
    #[serde(default = "default_server_name")]
    pub server_name: String,
    /// Server version announced during initialization.
    #[serde(default = "default_server_version")]
    pub server_version: String,
    /// Explicit list of tool names to expose. Only these tools will appear in
    /// `tools/list` and be callable via `tools/call`.
    #[serde(default)]
    pub allowlisted_tools: Vec<String>,
    /// Whether to expose tools classified as dangerous. Default: `false`.
    #[serde(default)]
    pub expose_dangerous: bool,
}

fn default_server_name() -> String {
    "layers".to_string()
}

//! Pure context-packet compiler primitives.
//!
//! This crate is intentionally side-effect free. CLI, MCP, and future agent
//! integrations can assemble sections from their own adapters, then call these
//! helpers to normalize packet shape, citations, and compatibility evidence.

use std::path::Path;

use chrono::{DateTime, Utc};
use layers_core::{ContextItem, ContextPacket, ContextSection, ContextSource, ContextWarning};

/// Compiler mode used to preserve caller intent in generated packet metadata.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompileMode {
    /// Compile context for a query/injection flow.
    Query,
    /// Compile context for preflight validation before coding-agent work.
    Preflight,
    /// Compile context for stable MCP tool callers.
    Mcp,
}

impl CompileMode {
    #[must_use]
    pub const fn route(self) -> &'static str {
        match self {
            Self::Query => "query",
            Self::Preflight => "preflight",
            Self::Mcp => "mcp",
        }
    }
}

/// Side-effect-free request for building a `ContextPacket` from caller-supplied context.
#[derive(Debug, Clone)]
pub struct CompileRequest {
    pub packet_id: String,
    pub workspace_id: String,
    pub objective: String,
    pub generated_at: DateTime<Utc>,
    pub mode: CompileMode,
    pub route_label: Option<String>,
    pub sections: Vec<ContextSection>,
    pub warnings: Vec<ContextWarning>,
    pub git_ref: Option<String>,
    pub derive_evidence: bool,
}

impl CompileRequest {
    #[must_use]
    pub fn new(
        packet_id: impl Into<String>,
        workspace_id: impl Into<String>,
        objective: impl Into<String>,
        generated_at: DateTime<Utc>,
        mode: CompileMode,
    ) -> Self {
        Self {
            packet_id: packet_id.into(),
            workspace_id: workspace_id.into(),
            objective: objective.into(),
            generated_at,
            mode,
            route_label: None,
            sections: Vec::new(),
            warnings: Vec::new(),
            git_ref: None,
            derive_evidence: true,
        }
    }

    #[must_use]
    pub fn with_sections(mut self, sections: Vec<ContextSection>) -> Self {
        self.sections = sections;
        self
    }

    #[must_use]
    pub fn with_warnings(mut self, warnings: Vec<ContextWarning>) -> Self {
        self.warnings = warnings;

